{
  "service": "phase2-complex",
  "action": "echo",
  "componentType": "rest",
  "description": "Runnable Phase 2 JSON echo with all supported sections",
  "config": {
    "request": {
      "uri": "{{upstream_url}}/anything",
      "method": "POST",
      "contentType": "application/json",
      "headers": { "X-Customer-Id": "{$context.id}", "X-Request-Label": "demo-{$context.label}" },
      "payloadTemplate": { "customerId": "{$context.id}", "name": "{$context.name}", "items": "{$context.items}" },
      "validation": { "fields": [ { "path": "id", "required": true, "type": "string" }, { "path": "name", "required": true, "type": "string" }, { "path": "items", "required": true, "type": "array", "minItems": 1 }, { "path": "items[*].sku", "required": true, "type": "string" } ] }
    },
    "timeout": { "response": 5000 },
    "resilience": {
      "retryCount": 2, "retryDelay": 100, "backoff": "exponential", "maxDelay": 1000,
      "retryOn": [500, 502, 503]
    },
    "output": {
      "validation": { "rules": [{ "expression": "{$output.json.customerId} != null", "message": "Echo omitted customer ID", "errorPath": "{$output.message}" }] },
      "default": { "json": { "customerId": "no-body" } },
      "transformation": { "echoResponse": { "customerId": "{$output.json.customerId}", "name": "{$output.json.name}", "items": "{$output.json.items}" } }
    }
  },
  "condition": "{$context.enabled} == true && {$context.id} != null",
  "metaData": { "example": "phase2", "purpose": "dummy-data-only" }
}

{
  "service": "phase2-complex", "action": "form", "componentType": "rest",
  "config": {
    "request": { "uri": "{{upstream_url}}/anything", "method": "POST", "contentType": "application/x-www-form-urlencoded", "headers": { "X-Demo": "{$context.id}" }, "payloadTemplate": { "customerId": "{$context.id}", "label": "{$context.label}" }, "validation": { "fields": [ { "path": "id", "required": true, "type": "string" }, { "path": "label", "required": true, "type": "string" } ] } },
    "timeout": { "response": 5000 },
    "resilience": { "retryCount": 1, "retryDelay": 100, "backoff": "fixed", "maxDelay": 500, "retryOn": [502, 503] },
    "output": { "validation": { "rules": [{ "expression": "{$output.form.customerId} != null", "message": "Missing form ID", "errorPath": "{$output.message}" }] }, "default": { "form": {} }, "transformation": { "formEchoResponse": { "customerId": "{$output.form.customerId}", "label": "{$output.form.label}" } } }
  },
  "condition": "{$context.id} != null", "metaData": { "example": "phase2-form" }
}

{
  "service": "phase2-complex", "action": "default", "componentType": "rest",
  "config": {
    "request": { "uri": "{{upstream_url}}/status/204", "method": "GET", "contentType": "application/json", "headers": { "X-Demo": "{$context.id}" }, "payloadTemplate": { "unusedForGet": "{$context.id}" }, "validation": { "fields": [ { "path": "id", "required": true, "type": "string" } ] } },
    "timeout": { "response": 5000 },
    "resilience": { "retryCount": 1, "retryDelay": 100, "backoff": "fixed", "maxDelay": 500, "retryOn": [503] },
    "output": { "validation": { "rules": [{ "expression": "true", "message": "Default scenario permits an empty response" }] }, "default": { "status": "empty" }, "transformation": { "defaultResponse": { "status": "{$output.status}", "customerId": "{$context.id}" } } }
  },
  "condition": "{$context.id} != null", "metaData": { "example": "phase2-default" }
}

request.description:
NOT_FOUND with execution metadata; failed record attempts=0.

Expected error envelope:
```json
{
  "error": {
    "code": "NOT_FOUND",
    "message": "Service not found: phase2-never-registered/missing"
  }
}
```

VALIDATION_FAILED, wire data=null. Lookup must contain validationFailureResponse.upstream and injected validationFailureResponse.error.

Expected error envelope:
```json
{
  "error": {
    "code": "VALIDATION_FAILED",
    "message": "Intentional demo validation failure",
    "details": [
      {
        "rule": "false",
        "message": "Intentional demo validation failure",
        "path": "false"
      }
    ]
  }
}
```

NOT_IMPLEMENTED, attempts=0, no env resolution or unauthenticated upstream dispatch.

Expected error envelope:
```json
{
  "error": {
    "code": "NOT_IMPLEMENTED",
    "message": "Configured but not implemented: config.request.auth.jwt",
    "details": {
      "unsupported": [
        { "field": "config.request.auth.jwt", "phase": "Phase 4" }
      ]
    }
  }
}
```

EXTERNAL_ERROR after two actual attempts. One execution and one audit row; failed transformed result contains upstreamFailureResponse.error.

Expected error envelope:
```json
{
  "error": {
    "code": "EXTERNAL_ERROR",
    "message": "External API returned 503",
    "details": {
      "body": {}
    }
  }
}
```

EXTERNAL_ERROR after one attempt. Upstream 404 is not the runtime's own NOT_FOUND.

Expected error envelope:
```json
{
  "error": {
    "code": "EXTERNAL_ERROR",
    "message": "External API returned 404",
    "details": {
      "body": {}
    }
  }
}
```

