{
  "service": "user-service",
  "action": "get_user",
  "componentType": "rest",
  "description": "Fetch user by ID from upstream API",
  "config": {
    "request": {
      "uri": "https://jsonplaceholder.typicode.com/users/{$context.id}",
      "method": "GET"
    },
    "output": {
      "transformation": {
        "getUserResponse": {
          "userId": "{$output.id}",
          "userName": "{$output.name}",
          "userEmail": "{$output.email}"
        }
      }
    }
  }
}

{
  "service": "order-service",
  "action": "create_order",
  "componentType": "rest",
  "description": "Create order in upstream system with auth, retry, and response mapping",
  "config": {
    "request": {
      "uri": "https://api.example.com/orders",
      "method": "POST",
      "contentType": "application/json",
      "headers": {
        "X-Tenant-Id": "{$context.tenantId}",
        "X-Request-Id": "{$context.requestId}"
      },
      "auth": {
        "oauth2": {
          "clientId": "{$env.ORDER_API_CLIENT_ID}",
          "clientSecret": "{$env.ORDER_API_CLIENT_SECRET}",
          "accessTokenUri": "https://auth.example.com/oauth/token",
          "scope": "orders:write"
        }
      },
      "payloadTemplate": {
        "customerId": "{$context.customerId}",
        "items": "{$context.items}",
        "totalAmount": "{$context.totalAmount}"
      },
      "validation": {
        "fields": [
          { "path": "tenantId", "required": true, "type": "string" },
          { "path": "customerId", "required": true, "type": "string" },
          { "path": "items", "required": true, "type": "array", "minItems": 1 },
          { "path": "totalAmount", "required": true, "type": "number" }
        ]
      }
    },
    "timeout": {
      "connect": 5000,
      "response": 30000
    },
    "resilience": {
      "retryCount": 3,
      "retryDelay": 1000,
      "backoff": "exponential",
      "retryOn": [502, 503, 504]
    },
    "output": {
      "validation": {
        "rules": [
          { "expression": "{$output.id} != null", "message": "Order ID is missing" },
          { "expression": "{$output.status} == 'created'", "message": "Order not created" }
        ]
      },
      "transformation": {
        "createOrderResponse": {
          "orderId": "{$output.id}",
          "status": "{$output.status}",
          "createdAt": "{$output.created_at}"
        }
      }
    }
  },
  "condition": "{$context.customerId} != null",
  "metaData": {
    "owner": "platform-team",
    "slack": "#orders-alerts"
  }
}

{
  "service": "order-service",
  "action": "create_order",
  "componentType": "rest",
  "description": "Updated: increased timeout and added circuit breaker",
  "config": {
    "request": {
      "uri": "https://api.example.com/orders",
      "method": "POST",
      "contentType": "application/json",
      "auth": {
        "oauth2": {
          "clientId": "{$env.ORDER_API_CLIENT_ID}",
          "clientSecret": "{$env.ORDER_API_CLIENT_SECRET}",
          "accessTokenUri": "https://auth.example.com/oauth/token",
          "scope": "orders:write"
        }
      },
      "payloadTemplate": {
        "customerId": "{$context.customerId}",
        "items": "{$context.items}",
        "totalAmount": "{$context.totalAmount}"
      },
      "validation": {
        "fields": [
          { "path": "tenantId", "required": true, "type": "string" },
          { "path": "customerId", "required": true, "type": "string" },
          { "path": "items", "required": true, "type": "array", "minItems": 1 },
          { "path": "totalAmount", "required": true, "type": "number" }
        ]
      }
    },
    "timeout": {
      "connect": 5000,
      "response": 60000
    },
    "resilience": {
      "retryCount": 3,
      "retryDelay": 1000,
      "backoff": "exponential",
      "retryOn": [502, 503, 504],
      "circuitBreaker": {
        "failureThreshold": 5,
        "windowSize": 60000,
        "openDuration": 30000,
        "halfOpenMaxAttempts": 3
      }
    },
    "output": {
      "validation": {
        "rules": [
          { "expression": "{$output.id} != null", "message": "Order ID is missing" },
          { "expression": "{$output.status} == 'created'", "message": "Order not created" }
        ]
      },
      "transformation": {
        "createOrderResponse": {
          "orderId": "{$output.id}",
          "status": "{$output.status}",
          "createdAt": "{$output.created_at}"
        }
      }
    }
  }
}

