{
  "service": "tls-orders",
  "action": "create_order_encrypted_key",
  "componentType": "rest",
  "description": "Complex: an encrypted PKCS#8 private key (`-----BEGIN ENCRYPTED PRIVATE KEY-----`) with its `passphrase`, and a base64-DER root next to a PEM one. The passphrase is masked in logs and API responses. Returns 201.",
  "config": {
    "request": {
      "uri": "https://orders.partner.example.com/v2/orders",
      "method": "POST",
      "contentType": "application/json",
      "headers": {
        "X-Tenant-Id": "{$context.tenantId}",
        "X-Request-Id": "{$context.requestId}"
      },
