{
  "service": "ek",
  "action": "get_eligibility",
  "componentType": "rest",
  "description": "Complex: client_credentials with clientAuth basic (Authorization: Basic base64(id:secret)), a space-delimited scope list, an audience parameter and its own token-endpoint TLS via auth.ssl. Executes at invoke time (the token is fetched with client_credentials and cached); the hosts in this example are placeholders, so invoking it as-is fails to connect.",
  "config": {
    "request": {
      "uri": "https://api.example.com/olci/v1/eligibility",
      "method": "POST",
      "contentType": "application/json",
      "headers": { "X-Correlation-Id": "{$context.correlationId}" },
      "auth": {
        "ssl": { "ca": "{$env.IDP_CA_PEM}" },
        "oauth2": {
          "clientId": "{$env.EMIRATES_CLIENT_ID}",
          "clientSecret": "{$env.EMIRATES_CLIENT_SECRET}",
          "accessTokenUri": "https://authuat.emirates.dev/oauth2/<authServerId>/v1/token",
          "clientAuth": "basic",
          "scope": "ek.olci.onlineCheckIn.randomizer.get.eligibility ek.cab.rebooking.eligibility.post ek.ibe.flightPricing.airFares.get",
          "audience": "api://skywards"
        }
      },
      "payloadTemplate": { "pnr": "{$context.pnr}", "channel": "resConnect" },
      "validation": {
        "fields": [
          { "path": "pnr", "required": true, "type": "string" },
          { "path": "channel", "required": true, "type": "string" }
        ]
      }
    },
    "timeout": { "response": 10000 },
    "resilience": { "retryCount": 1, "retryDelay": 300, "backoff": "exponential", "retryOn": [502, 503, 504] },
    "output": {
      "validation": { "rules": [{ "expression": "{$output.eligible} != null", "message": "eligible flag is missing" }] },
      "transformation": { "getEligibilityResponse": { "eligible": "{$output.eligible}", "pnr": "{$context.pnr}" } }
    }
  },
  "condition": "{$context.pnr} != null",
  "metaData": { "owner": "ek-integrations", "auth": "oauth2-client-credentials" }
}

{
  "service": "resconnect",
