{
  "service": "data-mapper",
  "action": "enrich_order",
  "componentType": "mapper",
  "description": "Enrich order data with computed fields",
  "config": {
    "template": {
      "orderId": "{$context.orderId}",
      "totalWithTax": "{$context.subtotal} * 1.1",
      "itemCount": "{$context.items.length}"
    },
    "validation": { "fields": [ { "path": "orderId", "required": true, "type": "string" }, { "path": "subtotal", "required": true, "type": "number" } ] },
    "condition": "{$context.orderId} != null",
    "output": {
      "transformation": {
        "enrichOrderResponse": {
          "orderId": "{$context.output.enrichOrderResponse.orderId}",
          "totalWithTax": "{$context.output.enrichOrderResponse.totalWithTax}"
        }
      }
    }
  }
}

{
  "service": "customer-db",
  "action": "get_customer",
  "componentType": "database",
  "description": "Fetch customer by ID",
  "config": {
    "operation": "SELECT",
    "query": "SELECT * FROM customers WHERE id = $id",
    "parameters": {
      "id": "{$context.customerId}"
    },
    "output": {
      "transformation": {
        "getCustomerResponse": {
          "customer": "{$output.rows}[0]"
        }
      }
    }
  }
}

{
  "service": "order-db",
  "action": "save_order",
  "componentType": "database",
  "description": "Save order to database",
  "config": {
    "operation": "INSERT",
    "query": "INSERT INTO orders (customer_id, total, status) VALUES ($customerId, $total, $status) RETURNING *",
    "parameters": {
      "customerId": "{$context.customerId}",
      "total": "{$context.total}",
      "status": "{$context.status}"
    },
    "validation": { "fields": [ { "path": "customerId", "required": true, "type": "string" }, { "path": "total", "required": true, "type": "number" }, { "path": "status", "required": true, "type": "string" } ] },
    "output": {
      "validation": {
        "rules": [
          { "expression": "{$output.rows} != null", "message": "Order not saved" }
        ]
      },
      "transformation": {
        "saveOrderResponse": {
          "orderId": "{$output.rows}[0].id",
          "createdAt": "{$output.rows}[0].created_at"
        }
      }
    }
  }
}

{
  "service": "calc-service",
  "action": "calculate_total",
  "componentType": "script",
  "description": "Marks an audit variable, calls echo with the implicit $context, then computes the total",
  "condition": "{$context.skip} != true",
  "metaData": { "owner": "platform-team" },
  "config": {
    "expression": "async function ($context) { $context.auditMarker = { touchedBy: 'calc-script' }; const echoed = await apiconfy.invoke('echo-service', 'echo'); $context.calculateTotalResponse = { total: $context.subtotal * 1.1, label: `Order for ${$context?.customer?.name ?? 'anonymous'}`, echoOk: echoed?.success === true, echoExecution: echoed?.meta?.executionId }; $context.customer = { ...$context.customer, verified: true }; }"
  }
}

{
  "service": "order-queue",
  "action": "enqueue_order",
  "componentType": "sqs",
  "description": "Push order to FIFO queue",
  "config": {
    "queueName": "order-queue.fifo",
    "isFifo": true,
    "groupId": "{$context.orderGroupId}",
    "messageBody": {
      "orderId": "{$context.orderId}",
      "customerId": "{$context.customerId}",
      "total": "{$context.total}"
    },
    "validation": { "fields": [ { "path": "orderId", "required": true, "type": "string" }, { "path": "customerId", "required": true, "type": "string" }, { "path": "total", "required": true, "type": "number" } ] },
    "condition": "{$context.orderId} != null",
    "output": {
      "transformation": {
        "enqueueOrderResponse": {
          "messageId": "{$output.messageId}",
          "sequenceNumber": "{$output.sequenceNumber}"
        }
      }
    }
  }
}
